            if cells:
                blocks.append((r, c, cells))

    # Within each sequence of repeated blocks, the marked position advances.
    groups = {}
    for r, c, cells in blocks:
        groups.setdefault(r, []).append((c, cells))

    for row, seq in groups.items():
